			text.append("heap used=")
					.append(runtime.totalMemory() - runtime.freeMemory())
					.append(" committed=")
					.append(runtime.totalMemory())
					.append(" max=")
					.append(runtime.maxMemory())
					.append('\n');
			ManagementFactory.getGarbageCollectorMXBeans()
					.stream()
					.limit(8)
					.forEach(gc -> text.append("gc ")
							.append(gc.getName())
							.append(" count=")
							.append(gc.getCollectionCount())
							.append(" timeMs=")
							.append(gc.getCollectionTime())
							.append('\n'));
			text.append("configuredMapBytes values=")
					.append(configuredValueBytes)
					.append(" triples=")
					.append(configuredTripleBytes)
					.append(" (configuration, not current native capacity)\n")
					.append("mapGrowthCount bestEffortNonvolatileNonAtomicCrossEnvironmentObservation=")
					.append(observedGrowthCount.getAsLong())
					.append(" (not proof of no growth)\n");
