	private void appendThreads(StringBuilder text) {
		text.append("DIRECT_CALLER name=")
				.append(caller.getName())
				.append(" id=")
				.append(caller.threadId())
				.append(" virtual=")
				.append(caller.isVirtual())
				.append(" state=")
				.append(caller.getState())
				.append('\n');
		appendStack(text, caller.getStackTrace());
		ThreadMXBean threads = ManagementFactory.getThreadMXBean();
		boolean cpu = threads.isThreadCpuTimeSupported() && threads.isThreadCpuTimeEnabled();
		text.append("ThreadMXBean: platform threads only; other virtual threads omitted; CPU accounting=")
				.append(cpu ? "already enabled" : "unsupported/disabled (not enabled by diagnostics)")
				.append('\n');
		ThreadInfo[] headers = threads.getThreadInfo(threads.getAllThreadIds(), 0);
		long[] selected = Arrays.stream(headers)
				.filter(Objects::nonNull)
				.sorted(Comparator.comparingInt(this::threadPriority).thenComparingLong(ThreadInfo::getThreadId))
				.limit(MAX_THREADS)
				.mapToLong(ThreadInfo::getThreadId)
				.toArray();
		text.append("platformThreads observed=")
				.append(headers.length)
				.append(" sampled=")
				.append(selected.length)
				.append(" cap=")
				.append(MAX_THREADS)
				.append('\n');
		ThreadInfo[] sampled = threads.getThreadInfo(selected, threads.isObjectMonitorUsageSupported(),
				threads.isSynchronizerUsageSupported(), MAX_FRAMES);
		for (ThreadInfo thread : sampled) {
			if (thread == null) {
				continue;
			}
			text.append("THREAD name=")
					.append(thread.getThreadName())
					.append(" id=")
					.append(thread.getThreadId())
					.append(" state=")
					.append(thread.getThreadState())
					.append(" native=")
					.append(thread.isInNative())
					.append(" lock=")
					.append(thread.getLockInfo())
					.append(" owner=")
					.append(thread.getLockOwnerName())
					.append('/')
					.append(thread.getLockOwnerId())
					.append(" blockedCount=")
					.append(thread.getBlockedCount())
					.append(" waitedCount=")
					.append(thread.getWaitedCount())
					.append(" cpuNanos=")
					.append(cpu ? threads.getThreadCpuTime(thread.getThreadId()) : -1L)
					.append('\n');
			appendStack(text, thread.getStackTrace());
			Arrays.stream(thread.getLockedMonitors())
					.limit(8)
					.forEach(lock -> text.append("  owns monitor ")
							.append(lock)
							.append(" at depth ")
							.append(lock.getLockedStackDepth())
							.append('\n'));
			Arrays.stream(thread.getLockedSynchronizers())
					.limit(8)
					.forEach(lock -> text.append("  owns synchronizer ").append(lock).append('\n'));
		}
	}

	private int threadPriority(ThreadInfo thread) {
		if (thread.getThreadId() == caller.threadId()) {
			return 0;
		}
		if (thread.getThreadName().startsWith("LmdbTripleStore-Ingest-")) {
			return 1;
		}
		return thread.getThreadName().toLowerCase(java.util.Locale.ROOT).contains("lmdb") ? 2 : 3;
	}

	private static void appendStack(StringBuilder text, StackTraceElement[] stack) {
		Arrays.stream(stack).limit(MAX_FRAMES).forEach(frame -> text.append("  at ").append(frame).append('\n'));
		if (stack.length > MAX_FRAMES) {
			text.append("  [stack truncated]\n");
		}
	}

